cd /workspace && node -e "
const fs = require('fs');
const { execSync } = require('child_process');

// Try using unzip to extract docx content
execSync('mkdir -p /tmp/docx_extract');
execSync('unzip -o testbed/docs/customer_report.docx -d /tmp/docx_extract 2>/dev/null');
const xml = fs.readFileSync('/tmp/docx_extract/word/document.xml', 'utf-8');

// Extract text from the XML
const texts = [];
const regex = /<w:t[^>]*>(.*?)<\/w:t>/g;
let match;
while ((match = regex.exec(xml)) !== null) {
  texts.push(match[1]);
}
console.log(texts.join(''));
"

